namespace BinSite.Social.Services;

/// <summary>Twelve original, actionable editorial methods; none are fabricated public publications or user outcomes.</summary>
public static class ProcedureExchangeContent
{
    public static readonly ProcedureStarter[] All=
    [
        Make("clean-catalog-sheet","Turn a Product Sheet into a Checked Catalog","Prepare actual product rows, match local photos, and leave with a searchable catalog plus a record of unresolved data issues.","work",["csv","catalog","handoff"],["A product CSV you are allowed to use","Local photos you have permission to include","The intended currency and audience"],"A cleaned product CSV, an issue log and a standalone searchable catalog whose included rows have valid identifiers and prices.",
            ("Preserve the source","Keep the original sheet unchanged. Work on a named copy and record its filename, date and intended audience in your private run inputs. Decide whether this is a public catalog or an internal review copy before choosing fields.","The original is still available and the working copy has a distinct name and stated audience.",5),
            ("Define field meanings","Identify the SKU, display name, price, currency, category and image-filename columns. Choose a decimal convention explicitly. Do not silently interpret a tax-inclusive amount as a different kind of price; record ambiguities as unresolved issues.","Every output column has one stated source and ambiguous monetary fields are listed instead of guessed.",8),
            ("Find row conflicts","Check for blank or repeated included SKUs, missing names and invalid prices. For each conflict, write the source row and a specific repair. Exclude a row only deliberately; keep its original data in the working record.","Included rows have distinct nonempty SKUs, names and parseable nonnegative prices; every excluded row has a recorded reason.",12),
            ("Match photos deliberately","Match by exact image filename or an agreed SKU stem. Inspect ambiguous matches rather than selecting the first similar image. Record missing photos as visible placeholders if they cannot be supplied.","Each included image belongs to the intended product, and unmatched or ambiguous rows are visible in the issue log.",10),
            ("Check the actual export","Export the catalog, open that exported file and search for two known SKUs. Select a category that includes more than one product. Inspect a narrow view and a print preview using the same exported artifact.","The exported file opens, both searches find the intended products, and category/print checks refer to the exported file rather than only the editor.",8),
            ("Package the handoff","Keep the cleaned source, issue log and catalog together. State whether prices and stock are a dated snapshot. Write the filenames of the actual outputs in the artifact area instead of declaring completion from the checklist alone.","The handoff contains the actual files and a clear snapshot statement, with no unresolved issue hidden from the recipient.",5)),
        Make("revision-handoff","Deliver a Version-Linked Creative Revision","Keep feedback attached to exact media versions and produce an editing list and review record without inventing client approval.","creative",["review","versions","delivery"],["The original and revised image or video","The agreed delivery brief","The actual feedback you received, if any"],"A version-linked review report, an open editing list and an explicit record of what was reviewed or delivered.",
            ("Identify the two deliveries","Give the original and revised files separate version labels. Record exact filenames and file fingerprints where your review tool supports them. Do not replace the original file record with a newer file under the same label.","Two distinct file identities and version labels exist, and the original can still be inspected.",5),
            ("Anchor observations","Place image observations at normalized points or video observations at actual player times. Separate what was observed from the requested change. Mark a change as blocking only when it prevents the agreed delivery from being accepted.","Every actionable note names its exact version and a point, time or clearly identified location.",10),
            ("Compare the revision","Inspect the revised file against each original request. Record a new note on the revised version if the issue remains; do not silently transfer a resolved label from an older version. Keep unrelated observations separate.","Each original request has an explicit disposition, and remaining issues point to the revised file.",12),
            ("Record an honest decision","Resolve actual blocking issues before recording your review decision. Distinguish your local approval record from any approval a customer actually supplied. If a response is still pending, say so instead of recording it on someone else's behalf.","The decision states who made the record and what remains pending; no missing customer response is represented as approval.",5),
            ("Export and inspect the handoff","Export the review report and open editing list. Check that filenames, versions and positions survived the export. Put the actual delivered files and the report identifiers into the artifact area.","The recipient can identify the intended versions and outstanding work from the exported report without relying on your open browser tab.",7)),
        Make("small-playtest","Prepare a Five-Minute Prototype Playtest","Create a short, observable task script and a result log before asking another person to try your prototype.","creative",["prototype","testing","feedback"],["A prototype you own or may test","One question the test should answer","A willing participant, or a clearly labelled solo rehearsal"],"Three neutral test tasks, an observation log and a prioritized next-version change list.",
            ("Choose one uncertainty","Write one question about behavior: for example, whether a newcomer can find the next action. Avoid a broad request to prove that the entire product is good. State the prototype version being examined.","The test has one answerable behavior question and a specific prototype version.",5),
            ("Write three neutral tasks","Describe three goals without telling the participant which button to press. For each, write the starting state and an observable finish. Keep the combined task script short enough for the intended session.","Each task has a start and finish and does not contain the solution in its wording.",8),
            ("Rehearse honestly","Run the script yourself to find broken links, missing permissions and impossible starts. Label this as a solo rehearsal. Do not record yourself as an independent participant or invent observations from another person.","The script is runnable and rehearsal notes are explicitly separate from participant observations.",5),
            ("Record what happened","If someone participates, ask permission to take the notes you need. Record task completion, points of hesitation and exact words only when actually observed. Keep interpretations in a separate column and avoid collecting unrelated personal information.","The log distinguishes observation, quotation and interpretation, and contains no fabricated participant activity.",10),
            ("Choose the next change","Group repeated issues, choose a small next change and state what a retest would observe. Keep issues you did not address visible. The artifact is the task script and real log, even if no participant has arrived yet.","The next-version list links each proposed change to a real observation or clearly labelled rehearsal issue.",7)),
        Make("event-info-pack","Prepare a Clear Event Information Pack","Turn confirmed event facts into consistent web and print information with an explicit source of truth.","community",["event","publishing","coordination"],["Confirmed event date, time zone and place or online access method","An organizer-approved description","Assets and contact details you are permitted to publish"],"A consistent one-page event pack and an open-question list that another organizer can update.",
            ("Separate facts from open questions","List confirmed details and unresolved questions separately. Record who can confirm each question. Do not invent a venue, capacity, accessibility arrangement or attendance number to make the page look complete.","Every uncertain public detail is either confirmed by its responsible source or clearly marked pending.",8),
            ("Create one source record","Put the title, full date, time zone, access instructions and intended audience in one working record. Use that record to prepare all versions so the web page and print sheet do not drift independently.","There is one named source record and every output uses the same confirmed date and access information.",7),
            ("Write the visitor's path","Explain what a person should do before arrival, on arrival and if plans change. Use clear headings. Include only contact information the organizer has authorized for publication.","A newcomer can identify the next action and a legitimate way to ask an unresolved question.",10),
            ("Inspect the actual outputs","Check a narrow screen, printed page and copied text. Follow the actual access link if one is used. Make sure essential information is not communicated only by color, image or an unexplained abbreviation.","The exported or published artifacts retain the essential details and their actual access link has been checked.",8),
            ("Assign the update route","Write who maintains the source record and how a changed fact will reach every output. Do not assign a real person without agreement. List the final files or URLs in the run artifact.","The handoff names an agreed update responsibility and the actual current outputs.",5)),
        Make("release-note","Write Release Notes from Actual Changes","Produce a reader-focused release note grounded in delivered behavior and observed limitations.","work",["release","documentation","evidence"],["The actual change list or commits","The tested product version","A defined reader group"],"A release note with concrete behavior changes, relevant limitations and a linked verification checklist.",
            ("Collect the real changes","Gather the changes that are actually included in the release. Mark experiments, plans and unfinished work separately. Use the product version as the boundary rather than the entire conversation or backlog.","Every candidate release-note item belongs to the actual release, with plans separated.",8),
            ("Describe the trigger and result","For each important change, write when the reader encounters it and what now happens. Prefer a concrete before/after example to a list of internal filenames. Keep implementation detail only where it helps a reader act.","Each main item explains a user-visible trigger and resulting behavior.",10),
            ("Match claims to evidence","Check whether each claim comes from source inspection, a local check or production observation. Do not turn a successful build into proof of a complete workflow or a deployment into proof of user demand.","The verification checklist distinguishes the evidence supporting each claim.",8),
            ("Retain material limits","State a limitation where it changes what the reader can do. Keep known incomplete behavior visible. Remove unrelated warnings and speculative future features that do not help the reader use this release.","A reader can see the actual boundary of the delivered behavior without a roadmap disguised as a feature list.",7),
            ("Read and deliver the exact note","Review the final exported note, check its referenced version and links, then store it beside the verification checklist. Record those actual artifacts in this run.","The final note names the correct release and its supporting checklist remains available.",5)),
        Make("publish-check","Check a Creative Publication Before It Goes Live","Review the actual text, assets and links that will be published rather than relying on the editor's appearance.","creative",["content","release","review"],["The final text and media files","The intended publishing destination","Your source and attribution records"],"A publication-ready package and a short record of corrected links, attribution and unresolved questions.",
            ("Freeze a review copy","Give the review copy a clear version name. Keep later edits separate until they are checked. State the destination and intended audience so the review has a defined scope.","The reviewed copy and intended destination are unambiguous.",4),
            ("Check the message","Read headings, captions and calls to action in order. Remove unexplained abbreviations and promises the content does not support. Confirm that a newcomer can identify what the piece is for.","The text gives a clear purpose and next action without unsupported claims.",8),
            ("Check source permission and credit","Use only material you are entitled to publish. Record the source and requested attribution for each external asset. If permission is uncertain, replace or omit the asset rather than assuming it.","Every included external asset has a recorded source and a clear basis for publication.",8),
            ("Follow the final links","Open the links from the actual review copy. Check labels, destinations and whether access requires an account the audience may not have. Do not enter private credentials into an unfamiliar destination.","Every essential link has been checked from the actual artifact and access requirements are stated.",6),
            ("Inspect and package","Check the exported file or publishing preview on a narrow view and with images unavailable where practical. List unresolved questions separately. Record the final artifact and the corrections made.","The final artifact remains understandable and unresolved questions are not presented as completed checks.",7)),
        Make("decision-actions","Turn Meeting Notes into Agreed Actions","Separate decisions, proposals and open questions, then create a usable action handoff without assigning consent to absent people.","work",["meeting","handoff","actions"],["Notes you are allowed to process","The actual decisions and open questions","A way to confirm ownership with the people involved"],"A decision record, explicit action list and unresolved-question queue.",
            ("Classify the notes","Mark each item as a decision, proposal, question or observation. If the notes do not establish that a decision was made, leave it as a proposal. Keep the source wording available.","No suggestion has become a decision merely because it appeared in the notes.",8),
            ("Write observable actions","For each agreed decision that requires work, define an output and a done check. Separate a discussion topic from an action someone can complete. Keep the action small enough to hand off.","Every action names a concrete output and how completion will be observed.",10),
            ("Confirm responsibility","Ask the proposed owner to confirm before marking ownership agreed. If confirmation is missing, label the action unassigned or pending. Do not make up a person's availability or acceptance.","Each owner is confirmed or clearly marked pending; no silent assignment is represented as consent.",8),
            ("Record timing and dependencies","Use agreed dates rather than invented urgency. Identify actions blocked by another output. Keep unresolved questions beside the actions so the next person can see why something cannot start.","Dates and dependencies have a stated source, and blocked work has a visible reason.",7),
            ("Send a faithful handoff","Review the actual action document with its source notes. Export the decision record, action list and question queue together. Record the exact files or destinations in the artifact field.","The handoff distinguishes agreed work from proposed work and retains its open questions.",5)),
        Make("community-session","Prepare a Small Community Working Session","Design a bounded session with a useful shared output, accessible instructions and an honest plan for unfinished work.","community",["facilitation","planning","output"],["A topic the group has agreed to work on","A realistic session length and participant range","A place to keep the shared output"],"A timed session plan, a shared-output template and a clear follow-up route.",
            ("Name the output","Write what the group should leave with: for example, a ranked question list or a draft plan. Avoid an unbounded goal such as solving every concern. State what is intentionally outside the session.","The output is concrete and the session boundary is explicit.",6),
            ("Break the time into stages","Allocate time for orientation, individual thinking, shared work and a closing check. Leave a buffer. Make the plan usable even when fewer people arrive than expected; do not assume attendees who have not confirmed.","The plan fits the available time and has a smaller-group alternative.",10),
            ("Write participation instructions","Explain how to contribute, pass and ask for clarification. Provide a text route for essential information rather than relying only on speech or color. Keep the instructions short enough to read at the start.","A newcomer can understand how to participate without guessing the group's conventions.",8),
            ("Prepare the working artifact","Create headings or fields for the actual shared output. Separate facts, suggestions and unresolved questions. Test the template yourself and label that check as preparation rather than a real group result.","A usable empty output template exists and contains no invented participant contributions.",8),
            ("Plan the closing handoff","Define how the group will review the output, confirm any responsibilities and preserve unfinished work. Record the session plan and template as this procedure's artifact; conducting the event is a separate run if needed.","The plan includes a real closing check and no unagreed follow-up ownership.",6)),
        Make("readable-handoff","Prepare a Readable Document Handoff","Make a short document usable through its headings, selectable text, meaningful image descriptions and inspectable final export.","work",["documents","readability","handoff"],["A document you can edit","The intended readers and use","The actual export format"],"A readable final document plus a record of checks and remaining access issues; no compliance certification is implied.",
            ("Map the reading order","Identify the title, sections and next action. Arrange headings so the reader can predict the structure. Remove heading styles that exist only to look large while conveying no hierarchy.","The document has a clear title and a coherent sequence of section headings.",8),
            ("Check text rather than appearance alone","Copy a paragraph from the final export and check that it is the intended text. Inspect whether tables and labels remain understandable. A polished screenshot is not a substitute for usable text.","The exported text can be selected and its reading sequence matches the intended content.",8),
            ("Describe essential images","For each informative image, write the information a reader needs if the image is unavailable. Do not repeat a filename as the description. If the image is decorative, do not pretend it contains essential information.","The document preserves the information carried by essential images in a meaningful text form.",10),
            ("Check navigation and layout","Follow links from the exported artifact and inspect a narrow view or zoomed page. Note clipped content, confusing labels and broken destinations. Treat these as observed checks, not a claim of complete automated accessibility verification.","Actual navigation and layout observations are recorded with remaining problems visible.",10),
            ("Package the final copy","Name the final version and keep the editable source if the recipient needs it. Add the actual checks and unresolved issues to the handoff. Record the files produced in the artifact field.","The recipient receives the intended version with a usable source and an honest check record.",5)),
        Make("reconcile-sheets","Reconcile Two Product Sheets Without Silent Overwrites","Compare old and new records by an explicit key, keep a mismatch queue, and record only changes you actually accept.","work",["csv","reconcile","data"],["An unchanged copy of the old sheet","An unchanged copy of the incoming sheet","The agreed record key and fields to compare"],"A duplicate/missing/mismatch queue and an accepted-change list linked to source rows.",
            ("Choose the record key","State which field identifies one record. Check blanks and duplicates in both sources before matching anything. A similar name is not automatically the same record; leave ambiguous pairs for review.","The matching key is explicit and duplicate/blank-key rows are separated from automatic comparisons.",8),
            ("Define comparison rules","List which fields matter and whether case, spaces or decimal representation may be normalized. Preserve the raw sources. Do not convert a meaningful difference into equality without recording the rule.","Each normalization rule is written and can be applied again to the same inputs.",8),
            ("Build the mismatch queue","Separate records missing on either side from changed fields and exact matches. Include source row references. Do not delete a record simply because it is absent from one incoming file.","Every mismatch has a type and a source reference; missing records are not silently removed.",12),
            ("Decide changes explicitly","Accept, reject or defer each proposed change. Record the reason for exceptions and the intended resulting value. If authority is unclear, leave it pending rather than assigning approval to someone else.","The accepted-change list contains explicit resulting values and deferred decisions remain visible.",12),
            ("Inspect the result","Apply accepted changes to a new working copy, then recheck key uniqueness and a sample of changed rows. Keep the originals, rules and decision queue beside the result. Record the actual output filenames.","The resulting sheet can be traced to the source and accepted-change list, with no unexplained overwrite.",8)),
        Make("photo-batch","Prepare a Consistent Product Photo Batch","Create a named, inspectable set of product images without overwriting originals or making unsupported product claims.","creative",["photos","batch","catalog"],["Original product images you may use","Required output dimensions and background","The SKU-to-filename convention"],"A consistent image batch, a filename/SKU manifest and an exception list.",
            ("Keep originals separate","Place the originals outside the output folder. Record their source and the required use. Decide the output naming convention before resizing, so two products do not receive the same destination name.","Originals remain unchanged and every planned output filename is unique.",6),
            ("Choose one reference treatment","Select the intended framing, dimensions and background. Try it on one ordinary image and one awkward image before processing the entire batch. Do not retouch a product into a feature it does not have.","The reference treatment works on both trial images and preserves the actual product information.",10),
            ("Process and track exceptions","Apply the agreed treatment. Set aside images that need a different crop or have insufficient source detail. Record the reason instead of forcing every file into a bad result.","Processed images and exception images are separated, with a reason for each exception.",15),
            ("Inspect the real files","Open the exported files, check dimensions and match filenames to SKUs. Inspect at a small catalog size as well as full size. Look for clipped labels, missing parts and incorrect product associations.","Actual output files have been checked for size, readability and correct product identity.",10),
            ("Create the batch manifest","List the SKU, output filename and any exception. Keep the reference treatment and original-source notes with the batch. Record the actual folder or archive name in the run artifact.","The recipient can map each output image to the intended SKU and identify unfinished exceptions.",6)),
        Make("sharing-safe-copy","Prepare a Sharing-Safe Project Copy","Make an explicit public handoff copy while keeping private input values, credentials and unrelated personal information out of it.","everyday",["privacy","export","handoff"],["The project you own or may share","A defined recipient or public destination","A separate place to retain the complete private original"],"A reviewed sharing copy, an inclusion/exclusion note and a successful reopen check.",
            ("Preserve the private original","Save a complete private copy before removing anything. State who will receive the sharing copy and why. Do not use the only original as the file you are about to simplify or publish.","A complete private original remains available separately from the sharing copy.",5),
            ("Choose what belongs in the copy","List the actual fields and files needed for the recipient's task. Exclude credentials, recovery keys, private run inputs, unrelated personal details and hidden working notes. Keep necessary attribution and source-version references.","The inclusion list serves the stated purpose and explicitly excludes private execution data.",10),
            ("Inspect the exported representation","Open the actual JSON, HTML or document you intend to share. Search for known private markers from your original and inspect linked or embedded media. Do not assume that a hidden panel in an editor means its data is absent from an export.","The actual sharing artifact has been inspected, and known private markers are absent.",10),
            ("Reopen without the original session","Use a fresh view or supported restore path to check the sharing copy. Note dependencies on local files or accounts. A recipient should not be promised access to media or a service that was never included.","The copy reopens as intended and any missing dependencies are clearly listed.",8),
            ("Record the handoff boundary","Name the final sharing file and state what it includes and excludes. Retain the private original yourself. Publish or send only after reviewing the exact artifact, not merely its filename.","The final copy, its intended recipient and its boundary are recorded without exposing the private original.",5))
    ];

    /// <summary>Builds stable editorial step IDs and complete reusable public-schema documents.</summary>
    static ProcedureStarter Make(string id,string title,string summary,string category,string[] tags,string[] inputs,string artifact,params (string Title,string Action,string Done,int Minutes)[] steps)=>new(id,new ProcedureDocument{Title=title,Summary=summary,Category=category,Tags=[..tags],Inputs=[..inputs],Artifact=artifact,Steps=steps.Select((step,index)=>new ProcedureStep{Id=$"step_{index+1}",Title=step.Title,Action=step.Action,DoneWhen=step.Done,Minutes=step.Minutes}).ToList()});
}
